// Chapter 4: the October release (F-N16): 722 manuscripts generated by OpenAI's internal model, published at once.
// 722 squares, one per manuscript (a 38 x 19 grid). About 4,000 problems (F-N17) is no longer spoken in v4; the page
// keeps it in small print with its wording (it does not say who posed the problems; R1).
import { label, background, M, C, narratedScene, sstep, clamp, vo } from '../../../engine';
import { bell, count, dots, grid, tiles, verse } from '../lib';

narratedScene({
  name: 'release', kind: 'page', chapter: 4, ch: ['检验', ''], split: 16, lead: 0.6, gap: 0.7, tail: 1.4,
  sfx: (at) => [[at('release'), 'chime', { midi: bell(12) }]],
  draw(lt) {
    background();
    const t = vo('release'), GRID = grid();
    dots(4000, 80, GRID.x - 40, GRID.y - 50, 9, 0.4 * sstep(t + 3.5, t + 5.0, lt));
    tiles(GRID.n, GRID.cols, GRID.x, GRID.y, GRID.cell, clamp((lt - t - 0.4) / 4.0), 1);
    const a = sstep(t, t + 0.8, lt);
    count('722', '篇手稿', M, 480, lt, t + 0.4, 4.0, a);
    verse('12', M - 34, 480, a, 48);
    label('OpenAI · 内部模型生成 · 372 个系列', M, 540, a, C.muted, 18);
    label('github.com/openai/math · 2026-10-06', M, 572, a, C.muted, 18);
    label('据 OpenAI 自述：评估中向模型提出了约 4000 个问题，再按成果的重要性整理成目录', M, 680, sstep(t + 3.5, t + 4.3, lt), C.fg2, 20);
  },
});
